export type ButtonVariant = "primary" | "secondary" | "accent" | "ghost" | "quiet" | "success";
export function Button({ variant = "primary", size = "sm", className = "", ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { variant?: ButtonVariant; size?: "xs" | "sm" | "md" }) {
  return <button type="button" {...props} className={`inline-flex items-center justify-center gap-1.5 rounded-full px-3 font-medium transition-colors disabled:opacity-40 ${size === "xs" ? "h-7 text-xs" : "h-8 text-[13px]"} ${variant === "accent" ? "bg-blue text-white" : variant === "primary" ? "bg-ink text-surface" : variant === "secondary" ? "bg-field text-ink" : "text-ink hover:bg-hover"} ${className}`} />;
}
export function GlideMenu({ children, className = "", highlightClassName = "", rowSelector = "[data-menu-row]" }: { children: ReactNode; className?: string; highlightClassName?: string; rowSelector?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const [position, setPosition] = useState<{ top: number; height: number } | null>(null);
  return <div ref={host} className={`relative group/glide-menu ${className}`} onPointerLeave={() => setPosition(null)} onPointerMove={event => {
    const row = (event.target as Element).closest<HTMLElement>(rowSelector);
    if (row && host.current) { const a = row.getBoundingClientRect(), b = host.current.getBoundingClientRect(); setPosition({ top: a.top - b.top, height: a.height }); }
  }}>{position && <span aria-hidden className={`pointer-events-none absolute left-0 right-0 transition-[top,height] duration-150 ${highlightClassName || "rounded-lg bg-hover"}`} style={position} />}{children}</div>;
}
export function EntityChip({ name }: { name: string }) { return <span className="inline-flex rounded-md bg-field px-1.5 font-medium">{name}</span>; }
export function ValuePill({ children, tone }: { children: ReactNode; tone?: string }) { return <span className="rounded-md bg-field px-1.5" style={tone ? { color: `var(--${tone})` } : undefined}>{children}</span>; }
export function Shimmer(props: HTMLAttributes<HTMLSpanElement>) { return <span {...props} />; }
export function StreamText({ text, onProgress, onDone }: { text: string; onProgress?: () => void; onDone?: () => void }) {
  const [length, setLength] = useState(0);
  const callbacks = useRef({ onProgress, onDone });
  useEffect(() => { callbacks.current = { onProgress, onDone }; });
  useEffect(() => {
    let at = 0;
